import type { CSSProperties } from "react";
import type { MediaAsset } from "../domain/media";

export const MEDIA_SIZES = {
  card: "(max-width: 767px) 100vw, (max-width: 1199px) 50vw, 25vw",
  detail: "(max-width: 767px) 100vw, 800px",
  hero: "100vw",
  thumbnail: "160px"
} as const;

/**
 * Responsive, SEO-safe media renderer. Uses the WebP variants generated by the
 * media library and preserves intrinsic dimensions to avoid CLS.
 */
export function HaniMediaImage({
  media,
  sizes = MEDIA_SIZES.card,
  loading = "lazy",
  fetchPriority = "auto",
  className,
  style,
  width,
  height
}: {
  media: MediaAsset;
  sizes?: string;
  loading?: "lazy" | "eager";
  fetchPriority?: "high" | "low" | "auto";
  className?: string;
  style?: CSSProperties;
  width?: number;
  height?: number;
}) {
  const variants = [...media.variants]
    .filter((variant) => variant.format === "webp")
    .sort((left, right) => left.width - right.width);
  const srcSet = variants
    .map((variant) => `${variant.url} ${variant.width}w`)
    .join(", ");

  return (
    <picture>
      {srcSet ? (
        <source type="image/webp" srcSet={srcSet} sizes={sizes} />
      ) : null}
      <img
        src={media.url}
        alt={media.altText}
        width={width ?? media.width}
        height={height ?? media.height}
        loading={loading}
        decoding="async"
        fetchPriority={fetchPriority}
        className={className}
        style={style}
        data-media-id={media.id}
      />
    </picture>
  );
}
